<?php require __DIR__.'/../includes/bootstrap.php'; require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$action=$_POST['action']??'';if($pdo&&$id){if($action==='delete')$pdo->prepare('DELETE FROM contact_messages WHERE id=?')->execute([$id]);elseif($action==='read')$pdo->prepare("UPDATE contact_messages SET status='read' WHERE id=?")->execute([$id]);}header('Location: messages.php');exit;}$rows=$pdo?$pdo->query('SELECT * FROM contact_messages ORDER BY created_at DESC')->fetchAll():[];?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Contact Messages</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><header><a class="brand" href="dashboard.php">ASMR Audio Admin</a><nav><a href="articles.php">Articles</a><a href="categories.php">Categories</a><a href="subscribers.php">Subscribers</a><a href="logout.php">Log out</a></nav></header><main class="container"><h1>Contact Messages</h1><?php foreach($rows as $row):?><article class="card" style="margin-bottom:16px"><p><strong><?=e($row['subject'])?></strong> · <?=e($row['status'])?></p><p><?=nl2br(e($row['message']))?></p><p class="muted">From <?=e($row['name'])?> &lt;<?=e($row['email'])?>&gt; · <?=e($row['created_at'])?></p><form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$row['id']?>"><input type="hidden" name="action" value="read"><button>Mark read</button></form> <form method="post" style="display:inline" onsubmit="return confirm('Delete this message?')"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$row['id']?>"><input type="hidden" name="action" value="delete"><button>Delete</button></form></article><?php endforeach;if(!$rows):?><p class="muted">No contact messages.</p><?php endif;?></main></body></html>
